const logMsg = '[VALIDATE] wc=' + wordCount + ' min=' + minWords + ' max=' + maxWords + ' attempt=' + wordCountRevisionAttempt + ' final=' + isFinalFallback + ' truncated=' + truncated;
try { console.log(logMsg); } catch(e) {}
const output = {
  jobId: ctx.jobId,
  content,
  wordCount,
  minWords,
  maxWords,
  targetWords: ctx.targetWords,
  wordCountValid: !narrationTooShort && !narrationTooLong && !repeatedFillerNarration,
  validationIssue: narrationTooShort ? 'NARRATION_WORD_COUNT_TOO_SHORT' : narrationTooLong ? 'NARRATION_WORD_COUNT_TOO_LONG' : repeatedFillerNarration ? 'REPEATED_FILLER_NARRATION' : null,
  wordCountRevisionAttempt,
  isFinalFallback,
  truncated,
  raw: {
    model: response.model || 'unknown',
    resultLength: raw ? String(raw).length : 0,
  },
};
return [{ json: JSON.parse(JSON.stringify(output)) }];

const { jobId, content } = $('Validate Output').first().json;
return content.scenes.map(scene => ({
  json: {
    job_id: jobId,
    scene_index: scene.index,
    narration: scene.narration,
    caption: scene.caption,
    image_prompt: scene.imagePrompt,
    duration_seconds: scene.durationSeconds,
    motion: scene.motion,
    transition: scene.transition,
    generation_status: 'pending'
  }
}));

const input = $input.first().json;
const request = $('Validate').first().json;
const jobId = request.jobId;
if (input.success === false) return [{ json: { success: false, jobId, error: input.error, durationAttempt: Number(request.durationAttempt || 0) } }];
const content = $('Validate Output').first().json.content;
return [{ json: { success: true, jobId, sceneCount: content.scenes.length, durationAttempt: Number(request.durationAttempt || 0) } }];

const input = $json.body ?? $json;
const jobId = input.jobId ?? input.id;
if (!jobId || !input.workerId || !input.leaseToken || input.attemptNumber == null || input.pipelineRevision == null) throw new Error('LEASE_CONTEXT_REQUIRED');
const stage = 'generate_script';
const itemKey = input.itemKey ?? ('job' === 'scene_set' ? 'all-scenes' : 'job');
const canonical = JSON.stringify({jobId, pipelineRevision: input.pipelineRevision, stage, itemKey, revision: input.currentRevision ?? input.pipelineRevision});
return [{json: {...input, jobId, stage, itemKey, stageHashInput: canonical, workerId: input.workerId, leaseToken: input.leaseToken, attemptNumber: Number(input.attemptNumber), pipelineRevision: Number(input.pipelineRevision)}}];

const {stageHashInput, ...context} = $('Hash Stage Input').first().json;
const state = $json.state;
const stageRunId = $json.stage_run_id;
const stateSet = ['STARTED','CACHED_SUCCESS','RUNNING','FAILED','INPUT_HASH_MISMATCH','INVALID_ITEM_KEY','UNKNOWN_OUTCOME'];
if (typeof state !== 'string' || stateSet.indexOf(state) === -1) throw new Error('WF04_LEDGER_STATE_UNSUPPORTED: ' + state);
if (typeof stageRunId !== 'string' || stageRunId.length === 0) throw new Error('STAGE_RUN_ID_REQUIRED');
const runToken = state === 'STARTED' ? $json.run_token : undefined;
let cachedOutput;
let reason;
if (state === 'STARTED') {
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(runToken || '')) throw new Error('RUN_TOKEN_REQUIRED');
} else if (state === 'CACHED_SUCCESS') {
  cachedOutput = $json.output;
  if (cachedOutput === undefined) throw new Error('CACHED_OUTPUT_MISSING');
} else {
  reason = $json.error ?? $json.details ?? $json.reason ?? null;
}
const routeByState = {
  STARTED: 'provider',
  CACHED_SUCCESS: 'cached',
  RUNNING: 'safe_stop_running',
  FAILED: 'failure_previous',
  INPUT_HASH_MISMATCH: 'failure_mismatch',
  INVALID_ITEM_KEY: 'failure_invalid_key',
  UNKNOWN_OUTCOME: 'failure_unknown'
};
const route = routeByState[state];
return [{json: {...context, stageState: state, stageRunId: stageRunId, runToken, cachedOutput, reason, route}}];

const context = $('Merge Stage Context').first().json;
if (typeof context.runToken !== 'string') throw new Error('RUN_TOKEN_REQUIRED');
if ($json.permitted !== true) throw new Error('EXTERNAL_ATTEMPT_LIMIT');
return [{json: {...context, externalAttempt: $json.attempt_number}}];

const context = $('Merge Attempt Context').first().json;
if (typeof context.runToken !== 'string') throw new Error('RUN_TOKEN_REQUIRED');
return [{json: {...context, cancelRequested: $json.cancel_requested === true}}];

const context = $('Merge Stage Context').first().json;
if (context.stageState !== 'CACHED_SUCCESS') throw new Error('STAGE_RECONCILIATION_REQUIRED');
return [{json: {success: true, cached: true, jobId: context.jobId, stage: context.stage, stageRunId: context.stageRunId, output: context.cachedOutput}}];

const context = $('Build Prompt').first().json;
const leaseContext = $('Merge Heartbeat Context').first().json;
const prevAttempt = Number($('Validate Output').first().json.wordCountRevisionAttempt || 0);
const newAttempt = prevAttempt + 1;
const currentCount = Number($json.wordCount);
const diff = context.targetWords - currentCount;
const absDiff = Math.abs(diff);
const isFinalFallback = newAttempt >= 4;
const prefix = isFinalFallback
  ? 'FINAL NARRATION LENGTH ADJUSTMENT. This is the last attempt.'
  : 'REVISION ATTEMPT ' + newAttempt + ':';
const previousNarration = ($('Validate Output').first().json.content?.fullNarration || '').trim();
const durationNote = ' The video is ' + context.requestedDuration + ' seconds long, so the full narration must fill that time.';
const expansionNote = diff > 0
  ? ' Expand the narration SUBSTANTIALLY. Use the previous narration as the base and elaborate every scene with concrete details, explanations, examples, and natural transitions. The expanded narration must contain between ' + context.minWords + ' and ' + context.maxWords + ' words (target: ' + context.targetWords + '). Do not repeat whole phrases as filler.'
  : ' Shorten the narration while preserving its meaning and scene sequence.';
const revisionPrompt = '\n\n' + prefix + ' The previous narration contained ' + currentCount + ' words. It must contain between ' + context.minWords + ' and ' + context.maxWords + ' words (target: ' + context.targetWords + ').' + durationNote + expansionNote + '\n\nPREVIOUS NARRATION:\n' + (previousNarration || '(none)') + '\n\nRewrite into a complete replacement JSON with all fields (title, description, hashtags, fullNarration, scenes). Every scene narration must be detailed. Do not insert repeated filler phrases; the word count must come from informative expansion, not repetition.';
return [{ json: { ...context, ...leaseContext, wordCountRevisionAttempt: newAttempt, isFinalFallback, prompt: context.prompt + revisionPrompt } }];

const input = $json;
const error = {
  type: 'NARRATION_WORD_COUNT_OUT_OF_RANGE_AFTER_REVISION',
  actual: input.wordCount,
  acceptedRange: input.minWords + '-' + input.maxWords,
  target: input.targetWords,
  revisionAttempts: input.wordCountRevisionAttempt || 0,
  truncated: input.truncated || false,
  model: (input.raw && input.raw.model) || 'unknown',
  resultLength: (input.raw && input.raw.resultLength) || 0
};
throw new Error(JSON.stringify(error));

const context = $('Build Word Count Revision').first().json;
if (typeof context.runToken !== 'string') throw new Error('RUN_TOKEN_REQUIRED');
return [{json: {...context, cancelRequested: $json.cancel_requested === true}}];
